"""Slugs generated by code, never by the model (IDEA-230): lowercase ASCII, capped,
never a Windows reserved device name, because the vault lives on a case-insensitive FS.
Letters without an NFKD decomposition (e.g. ß, ø, æ) are dropped by the ASCII fold below,
a known trade-off."""
from __future__ import annotations

import hashlib
import re
import unicodedata

MAX_LEN = 40
WINDOWS_RESERVED = ({"con", "prn", "aux", "nul"}
                    | {f"com{i}" for i in range(1, 10)}
                    | {f"lpt{i}" for i in range(1, 10)})


def slugify(text: str, max_len: int = MAX_LEN) -> str:
    original = text
    text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    text = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    text = text[:max_len].rstrip("-")
    if not text:
        digest = hashlib.sha1(original.encode("utf-8")).hexdigest()[:8]
        text = f"notebook-{digest}"
    if text in WINDOWS_RESERVED:
        text = f"{text}-nb"
    return text


def unique_slug(base: str, taken: set[str]) -> str:
    if base not in taken:
        return base
    n = 2
    while f"{base}-{n}" in taken:
        n += 1
    return f"{base}-{n}"
